1118	    this.staffTokens.clear();
1119	
1120	    for (const worker of this.state.workers) {
1121	      const location = this.visualLocation(worker);
1122	      const offset = offsets.get(location) ?? 0;
1123	      offsets.set(location, offset + 1);
1124	      const slot = this.stackedSlot(location, offset, layout);
1125	
1126	      const token = this.buildAvatar(slot.x, slot.y, worker.role, worker.load, compact);
1127	      this.staffTokens.set(worker.role, token);
1128	      const heldHost = worker.role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
1129	      const status = heldHost ? "acting" : (this.workerStatuses.get(worker.role) ?? this.workerStatus(worker));
1130	      this.drawWorkerBadge(token, status, compact, heldHost);
1131	      this.drawSpeechBubble(token, worker.role, compact);
