438	  private startIdleBob(token: Phaser.GameObjects.Container, restY: number, role: Role): void {
439	    if (!this.running) return;
440	    this.tweens.killTweensOf(token);
441	    token.setY(restY);
442	    this.tweens.add({
443	      targets: token,
444	      y: restY - 1.5,
445	      duration: 900 + (role.length % 3) * 140,
446	      yoyo: true,
447	      repeat: -1,
448	      ease: "Sine.easeInOut",
449	    });
450	  }
