628	    g.lineStyle(2, COLORS.ink, 0.5);
629	    g.strokeRoundedRect(zone.x, zone.y, zone.width, zone.height, compact ? 3 : 5);
630	    const text = this.add.text(zone.x + 5, zone.y + 4, label, {
631	      color: "#3b2b20",
632	      fontFamily: "Arial Narrow, sans-serif",
633	      fontSize: compact ? this.fs(7) : this.fs(9),
634	      fontStyle: "bold",
