1629	   * controls and a money figure; a first-time player had to infer tonight's
1630	   * target from a "/190" suffix and infer the next move from nothing at all.
1631	   * This band tracks the three conditions that can lose the night, names the
1632	   * one thing to do now, and keeps the last decision's receipt on screen
1633	   * after its toast has faded (#304).
1634	   *
1635	   * Kept quiet on purpose. Only a condition in trouble gets colour — a band
1636	   * of green chips reads as urgent when nothing is wrong, and then has no
1637	   * louder register left for when something is. Same reason the tag does not
1638	   * pulse for an open decision: the card is already modal and the top bar
1639	   * already flashes NEEDS A CALL, so a third alarm only adds noise.
1640	   *
1641	   * The content is computed by `arenaBrief`, which is pure and tested; this
1642	   * only lays it out. The training coach feeds the same "now" line rather
1643	   * than getting a banner of its own, so there is exactly one place on
1644	   * screen that answers "what do I do".
1645	   */
1646	  private drawBrief(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
1647	    const zone = layout.brief;
1648	    const compact = layout.compact;
1649	    const brief = arenaBrief(this.state);
1650	
1651	    g.fillStyle(COLORS.panel);
1652	    g.fillRoundedRect(zone.x, zone.y, zone.width, zone.height, 4);
1653	
1654	    const pad = compact ? 5 : 7;
1655	    const rowOne = zone.y + (compact ? 3 : 4);
1656	
1657	    // Row one: the tally, right-aligned, with the receipt for the last call
1658	    // sitting quietly on the left of it.
1659	    const chipColors: Record<"ok" | "warn" | "bad", { bg: string; fg: string }> = {
1660	      ok: { bg: "#3a2e24", fg: "#a99b8a" },
1661	      warn: { bg: "#6b5124", fg: "#f7e2b4" },
1662	      bad: { bg: "#7a2b26", fg: "#ffdcd6" },
1663	    };
1664	    let chipRight = zone.x + zone.width - pad;
1665	    for (const chip of [...brief.chips].reverse()) {
1666	      const colors = chipColors[chip.tone];
1667	      const text = this.add
1668	        .text(chipRight, rowOne, `${chip.label} ${chip.value}`, {
1669	          color: colors.fg,
1670	          backgroundColor: colors.bg,
1671	          fontFamily: MONO,
1672	          fontSize: compact ? this.fs(6) : this.fs(7),
1673	          fontStyle: "bold",
1674	          padding: { x: 3, y: 1 },
1675	        })
1676	        .setOrigin(1, 0);
1677	      chipRight -= text.width + 4;
1678	      if (chipRight < zone.x + pad) text.destroy();
1679	    }
1680	
1681	    if (brief.last) {
1682	      const room = chipRight - (zone.x + pad) - 6;
1683	      if (room > 60) {
1684	        this.add.text(zone.x + pad, rowOne + 1, `Last: ${brief.last}`, {
1685	          color: "#7f8f83",
1686	          fontFamily: MONO,
1687	          fontSize: compact ? this.fs(6) : this.fs(7),
1688	          wordWrap: { width: room },
1689	          maxLines: 1,
1690	        });
1691	      }
1692	    }
1693	
1694	    // Row two: the single next move, across the full width, tagged so the
1695	    // kind of problem reads before the sentence does.
1696	    const rowTwo = zone.y + (compact ? 13 : 17);
1697	    const tag = this.add
1698	      .text(zone.x + pad, rowTwo, brief.nowLabel, {
1699	        color: "#2b2118",
1700	        backgroundColor: "#f2cc5c",
1701	        fontFamily: MONO,
1702	        fontSize: compact ? this.fs(6) : this.fs(7),
1703	        fontStyle: "bold",
1704	        padding: { x: 3, y: 1 },
1705	      })
1706	      .setOrigin(0, 0);
1707	
1708	    const nowX = zone.x + pad + tag.width + 5;
1709	    this.add.text(nowX, rowTwo + 1, brief.now, {
1710	      color: "#fff3d6",
1711	      fontFamily: MONO,
1712	      fontSize: compact ? this.fs(6) : this.fs(8),
1713	      wordWrap: { width: Math.max(40, zone.x + zone.width - pad - nowX) },
1714	      maxLines: compact ? 2 : 1,
1715	    });
1716	  }
1717	
1718	}
1719	
1720	export interface RestaurantArenaSceneHandle {
1721	  render(state: RestaurantArenaState): void;
1722	  setWorkerStatus(role: Role, status: RestaurantArenaWorkerStatus): void;
1723	  destroy(): void;
1724	}
1725	
1726	export function mountRestaurantArenaScene(
1727	  parent: HTMLElement,
1728	  state: RestaurantArenaState,
1729	  onAction: (action: string) => void = () => {},
1730	  onUi: (action: "menu" | "restart" | "help") => void = () => {},
1731	): RestaurantArenaSceneHandle {
1732	  // Calling `game.scale.resize()` on a live game — at any point after
1733	  // construction, however long after, `Core.Events.READY` or not — reliably
1734	  // corrupts a framebuffer ("Framebuffer status: Incomplete Attachment") and
1735	  // leaves the canvas permanently blank in this renderer. So a genuine
1736	  // resize never calls `.resize()` on an existing game: it tears the game
1737	  // down and boots a fresh one at the new size instead — cheap, since this
1738	  // scene already repaints itself from scratch on every state change.
1739	  //
1740	  // `width`/`height` passed to `boot()` below are CSS pixels; `bootedWidth`/
1741	  // `bootedHeight` (compared against `parent`'s real box everywhere else in
1742	  // this function) track those CSS-pixel values. The `Phaser.Game` config
1743	  // gets them multiplied by `DPR` instead, so the backing store is the
1744	  // supersampled size `RestaurantArenaScene.dpr`'s camera zoom expects — see
1745	  // that field's comment for what goes wrong when this multiplier and the
1746	  // scene's own `dpr` disagree.
1747	  let game: Phaser.Game | undefined;
1748	  let scene: RestaurantArenaScene | undefined;
1749	  let destroyed = false;
1750	  let currentState = state;
1751	  let bootedWidth = 0;
1752	  let bootedHeight = 0;
1753	  let persistedToastState: OutcomeToastState | undefined;
1754	
1755	  const teardown = () => {
1756	    if (scene) {
1757	      persistedToastState = scene.getOutcomeToastState();
1758	    }
1759	    game?.destroy(true);
1760	    game = undefined;
1761	    scene = undefined;
1762	  };
1763	
1764	  const boot = (width: number, height: number) => {
1765	    if (destroyed) return;
1766	    if (game) return;
1767	    bootedWidth = width;
1768	    bootedHeight = height;
1769	    scene = new RestaurantArenaScene(currentState, onAction, onUi, persistedToastState);
1770	    game = new Phaser.Game({
1771	      type: Phaser.AUTO,
1772	      parent,
1773	      width: Math.round(width * DPR),
1774	      height: Math.round(height * DPR),
1775	      backgroundColor: COLORS.ink,
1776	      scene,
1777	      // NONE, not RESIZE: this game is never resized in place (see the
1778	      // teardown-and-reboot comment above) — Phaser doesn't need to watch
1779	      // for size changes of its own.
1780	      scale: { mode: Phaser.Scale.NONE },
1781	    });
1782	    scheduleVerification();
1783	  };
1784	
1785	  const reboot = (width: number, height: number) => {
1786	    if (destroyed || !parent.isConnected) return;
1787	    if (width <= 0 || height <= 0) return;
1788	    if (game && width === bootedWidth && height === bootedHeight) return;
1789	    teardown();
1790	    boot(width, height);
1791	  };
1792	
1793	  /**
1794	   * A cold start (a just-restarted dev server, a slow initial layout pass
1795	   * on a big window) can settle to its *true* box later than either the
1796	   * boot-time measurement below or this module's own `ResizeObserver`
1797	   * happened to catch — both can agree on the same too-small intermediate
1798	   * reading and never see a further "resize" to correct it from, since
1799	   * nothing about `parent` actually changes again afterward from the
1800	   * browser's point of view. A few delayed re-checks against the real box,
1801	   * independent of any resize *event*, catch that without needing one.
1802	   */
1803	  const scheduleVerification = () => {
1804	    for (const delay of [300, 1000, 3000]) {
1805	      setTimeout(() => {
1806	        if (destroyed || !parent.isConnected) return;
1807	        const rect = parent.getBoundingClientRect();
1808	        reboot(Math.round(rect.width), Math.round(rect.height));
1809	      }, delay);
1810	    }
1811	  };
1812	
1813	  // `getBoundingClientRect()` called the instant we're handed `parent` can
1814	  // still read stale/zero — the caller may have just set `innerHTML` and
1815	  // not yet given the browser a layout pass. ResizeObserver is the primary
1816	  // boot path; rAF polling is a backup for browsers where the first RO
1817	  // callback still arrives before layout settles.
1818	  let attempts = 0;
1819	  const tryBoot = () => {
1820	    if (destroyed || game) return;
1821	    const rect = parent.getBoundingClientRect();
1822	    if (rect.width > 64 && rect.height > 64) {
1823	      boot(Math.round(rect.width), Math.round(rect.height));
1824	      return;
1825	    }
1826	    attempts += 1;
1827	    if (attempts < 30) {
1828	      requestAnimationFrame(tryBoot);
1829	    }
1830	  };
1831	
1832	  let resizeTimer: ReturnType<typeof setTimeout> | undefined;
1833	  const observer =
1834	    typeof ResizeObserver !== "undefined"
1835	      ? new ResizeObserver((entries) => {
1836	          const rect = entries[0]?.contentRect;
1837	          if (!rect || rect.width <= 0 || rect.height <= 0) return;
1838	          const width = Math.round(rect.width);
1839	          const height = Math.round(rect.height);
1840	          if (!game) {
1841	            boot(width, height);
1842	            return;
1843	          }
1844	          if (width === bootedWidth && height === bootedHeight) return;
1845	          if (resizeTimer !== undefined) clearTimeout(resizeTimer);
1846	          resizeTimer = setTimeout(() => {
1847	            resizeTimer = undefined;
1848	            reboot(width, height);
1849	          }, 150);
1850	        })
1851	      : undefined;
1852	  observer?.observe(parent);
1853	  requestAnimationFrame(tryBoot);
1854	
1855	  return {
1856	    render: (next) => {
1857	      currentState = next;
1858	      scene?.setState(next);
1859	      if (scene) {
1860	        persistedToastState = scene.getOutcomeToastState();
1861	      }
1862	    },
1863	    setWorkerStatus: (role, status) => scene?.setWorkerStatus(role, status),
1864	    destroy: () => {
1865	      destroyed = true;
1866	      if (resizeTimer !== undefined) clearTimeout(resizeTimer);
1867	      observer?.disconnect();
1868	      teardown();
1869	    },
1870	  };
1871	}
