arguments.content:
/**
 * Where every piece of the Restaurant Arena floor goes, for a given canvas.
 *
 * This is the whole of the scene's geometry: one pure function, no Phaser, so
 * the awkward sizes (a phone-shaped window, a 4K desktop one) are testable
 * without booting a game. Two things it has to get right that a fixed layout
 * could not:
 *
 * - **It grows.** Every constant here is authored at the 520×740 baseline the
 *   scene was designed against and multiplied by `scale`, so a desktop window
 *   gets a bigger room with bigger text rather than the same small room
 *   floating in the middle of a lot of ink. `scale` follows whichever axis has
 *   the least room to spare, so growing one dimension alone never pushes
 *   content off the other.
 * - **It stops growing.** Past `MAX_SCALE` a bigger window is just a bigger
 *   window; below the compact thresholds the layout gives up on growth
 *   entirely and packs to the tight baseline sizes instead, because the
 *   alternative on a small window is text that grows into the panel next to
 *   it.
 *
 * Every rect returned is inside `0,0 → width,height`, at any size, including
 * sizes too small for the layout to be any good.
 */

export type ArenaRect = { x: number; y: number; width: number; height: number };
export type ArenaPoint = { x: number; y: number };
export type ArenaLocation = "floor" | "kitchen" | "pass" | "queue";

export interface RestaurantArenaLayout {
  compact: boolean;
  scale: number;
  feedBeside: boolean;
  topBar: ArenaRect;
  brief: ArenaRect;
  kitchen: ArenaRect;
  pass: ArenaRect;
  dining: ArenaRect;
  door: ArenaRect;
  doorStand: ArenaRect;
  waypoints: Record<ArenaLocation, ArenaPoint>;
  /** Y coordinate of the hallway line that runs through the pass zone. */
  spineY: number;
  tickets: ArenaRect;
  feed: ArenaRect;
}

/** The design size every constant in this file is authored at — `scale` 1. */
export const BASE_WIDTH = 520;
export const BASE_HEIGHT = 740;
/**
 * Past this the room stops growing. A 4× room on a big monitor is not four
 * times as readable; it just turns the ticket rail into billboards and pushes
 * the dining tables apart until the floor stops reading as one room.
 */
export const MAX_SCALE = 1.9;
/** Under either of these the layout packs tight and stops growing text. */
export const COMPACT_WIDTH = 460;
export const COMPACT_HEIGHT = 420;
/** The service log moves beside the floor once there is width for a rail. */
export const FEED_BESIDE_WIDTH = 600;
/**
 * The host stand is a click target with two lines of copy on it before it is
 * decoration, so it keeps a usable size even when the door zone around it has
 * been squeezed to nothing.
 */
export const MIN_STAND_WIDTH = 56;
export const MIN_STAND_HEIGHT = 22;

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

/**
 * Keeps a rect inside the canvas: slides it in if it hangs off an edge, and
 * only shrinks it when it is genuinely larger than the whole box. A no-op for
 * every window the layout below is actually laid out for — it exists so a
 * caller measuring a half-collapsed parent still gets rects it can draw.
 */
function fitRect(rect: ArenaRect, width: number, height: number): ArenaRect {
  const w = Math.min(rect.width, width);
  const h = Math.min(rect.height, height);
  return {
    x: clamp(rect.x, 0, Math.max(0, width - w)),
    y: clamp(rect.y, 0, Math.max(0, height - h)),
    width: Math.max(0, w),
    height: Math.max(0, h),
  };
}

export function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
  const boxWidth = Math.max(0, Math.round(width));
  const boxHeight = Math.max(0, Math.round(height));
  // Below this the layout is laid out as if the window were this big and then
  // clipped to what there actually is; there is no honest arrangement of a
  // kitchen, a pass, a dining room and a ticket rail in 200px.
  const w = Math.max(320, boxWidth);
  const h = Math.max(240, boxHeight);

  const compact = w < COMPACT_WIDTH || h < COMPACT_HEIGHT;
  const scale = compact ? 1 : clamp(Math.min(w / BASE_WIDTH, h / BASE_HEIGHT), 1, MAX_SCALE);
  const feedBeside = w >= FEED_BESIDE_WIDTH;
  /** A baseline-authored length in this layout's pixels. */
  const px = (n: number) => Math.round(n * scale);

  const margin = px(8);
  const gap = px(6);
  const topBarHeight = px(38);
  const briefHeight = px(32);

  const inner = Math.max(1, w - margin * 2);
  const briefY = margin + topBarHeight + gap;
  const bodyX = margin;
  const bodyY = briefY + briefHeight + gap;
  const available = Math.max(px(60), h - margin - bodyY);

  // The feed is a rail beside the floor on a wide window and a strip under it
  // otherwise. Beside is much the better shape — the floor keeps its full
  // height, and a tall narrow rail fits two lines per entry.
  let bodyWidth = inner;
  let bodyHeight = available;
  let feed: ArenaRect;
  if (feedBeside) {
    const feedWidth = clamp(Math.round(inner * 0.28), px(170), Math.round(inner * 0.42));
    bodyWidth = Math.max(px(200), inner - feedWidth - gap);
    feed = { x: bodyX + bodyWidth + gap, y: bodyY, width: inner - bodyWidth - gap, height: bodyHeight };
  } else {
    // The floor comes first: the feed takes a fifth of the window, but only
    // out of what is left after the floor and the rail have what they need.
    const floorFirst = Math.min(px(100), Math.max(0, available - px(24)));
    const feedHeight = clamp(Math.max(px(110), Math.round(h * 0.2)), 0, Math.max(0, available - floorFirst - gap));
    bodyHeight = available - feedHeight - gap;
