import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";

/**
 * Staff moving between stations, as geometry and time rather than as a redraw.
 *
 * A worker whose station changes used to blink from one zone to another, which
 * reads as the UI correcting itself rather than as a person crossing the room.
 * Everything needed to make it a walk instead lives here, Phaser-free:
 *
 * - `WALK_GRAPH` is the restaurant's actual topology — one hallway, kitchen at
 *   one end and the door at the other. You cannot get from the kitchen to the
 *   queue without passing the pass and crossing the dining room, so `bfsPath`
 *   never returns a route that skips them.
 * - `corridorPoints` turns a route into pixels that ride the hallway line,
 *   because the shortest path between two zones is a diagonal straight through
 *   the middle of somebody's dinner.
 * - `StaffWalker` is one worker's position over time: which hop they are on,
 *   which way they face, whether the player currently has them picked up.
 */

export type WalkNode = ArenaLocation;
export type Point = ArenaPoint;

/**
 * Kitchen — pass — floor — queue, wired as a single hallway. The pass and the
 * dining floor are through-stations, not destinations only: the graph has no
 * kitchen↔floor or floor↔kitchen shortcut, and no door that opens onto the
 * kitchen.
 */
export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
  kitchen: ["pass"],
  pass: ["kitchen", "floor"],
  floor: ["pass", "queue"],
  queue: ["floor"],
};

/** A brisk service walk. Fast enough to be over inside a tick, slow enough to see. */
export const WALK_SPEED_PX_PER_SEC = 200;

/**
 * The stations to walk through to get from `from` to `to`, inclusive of both
 * ends. `[]` if the two are not connected at all — impossible for the graph
 * above, but the caller does not have to know that.
 */
export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
  if (from === to) return [from];
  const seen = new Set<WalkNode>([from]);
  const queue: WalkNode[][] = [[from]];
  while (queue.length > 0) {
    const path = queue.shift()!;
    const tail = path[path.length - 1]!;
    for (const next of WALK_GRAPH[tail] ?? []) {
      if (seen.has(next)) continue;
      const extended = [...path, next];
      if (next === to) return extended;
      seen.add(next);
      queue.push(extended);
    }
  }
  return [];
}

/** Same pixel, give or take a rounding error. */
function samePoint(a: Point, b: Point): boolean {
  return Math.abs(a.x - b.x) < 0.01 && Math.abs(a.y - b.y) < 0.01;
}

/**
 * The pixels of a walk: start where the worker is standing, step out to the
 * hallway at `spineY`, ride it to the station's column, then turn in. Every
 * segment is axis-aligned, so nobody ever cuts a diagonal across the dining
 * room to save four pixels.
 *
 * The first point is where the walk starts, so the result is a polyline that
 * can be followed as-is.
 */
export function corridorPoints(
  start: Point,
  nodes: readonly WalkNode[],
  waypoints: Record<WalkNode, Point>,
  spineY: number,
): Point[] {
  const points: Point[] = [{ x: start.x, y: start.y }];
  const push = (point: Point) => {
    if (samePoint(points[points.length - 1]!, point)) return;
    points.push(point);
  };
  for (const node of nodes) {
    const slot = waypoints[node];
    if (!slot) continue;
    const at = points[points.length - 1]!;
    if (Math.abs(at.x - slot.x) >= 0.01) {
      // Sideways means down the hallway, never through the room.
      push({ x: at.x, y: spineY });
      push({ x: slot.x, y: spineY });
    }
    push({ x: slot.x, y: slot.y });
  }
  return points;
}

/** How long one straight hop takes at `WALK_SPEED_PX_PER_SEC`. */
export function hopDurationMs(from: Point, to: Point): number {
  const distance = Math.hypot(to.x - from.x, to.y - from.y);
  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
}

/**
 * Ease each hop rather than the whole walk: a worker leans into a leg of the
 * corridor and settles out of it, and the corners between legs stay crisp
 * instead of the whole trip sliding as one long glide.
 */
function ease(t: number): number {
  return t * t * (3 - 2 * t);
}

export class StaffWalker {
  x: number;
  y: number;
  facing: 1 | -1 = 1;
  walking = false;
  /** The player has this worker picked up; the pointer owns the position. */
  dragging = false;
  /** Where they belong — set the moment a walk starts, not when it ends. */
  node: WalkNode;

  private hops: Point[] = [];
  private from?: Point;
  private to?: Point;
  private hopMs = 0;
  private elapsed = 0;

  constructor(node: WalkNode, slot: Point) {
    this.node = node;
    this.x = slot.x;
    this.y = slot.y;
  }

  /** Teleport onto `slot`/`node` with no walk in progress (e.g. after a drop). */
  snap(slot: Point, node: WalkNode): void {
    this.x = slot.x;
    this.y = slot.y;
    this.node = node;
    this.walking = false;
    this.hops = [];
    this.from = undefined;
    this.to = undefined;
    this.hopMs = 0;
    this.elapsed = 0;
  }

  /** Walk to `target` from wherever they are standing, along the hallway. */
  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
    const slot = waypoints[target];
    if (!slot) return;
    const route = corridorPoints({ x: this.x, y: this.y }, bfsPath(this.node, target), waypoints, spineY);
    this.node = target;
    // The first point is the pixel they are already standing on.
    this.hops = route.slice(1);
    this.from = undefined;
    this.to = undefined;
    this.hopMs = 0;
    this.elapsed = 0;
    this.walking = this.hops.length > 0;
    if (this.walking) this.beginHop();
  }

  private beginHop(): void {
    const next = this.hops.shift();
    if (!next) {
      this.walking = false;
      this.from = undefined;
      this.to = undefined;
      return;
    }
    this.from = { x: this.x, y: this.y };
    this.to = next;
    this.hopMs = hopDurationMs(this.from, this.to);
    this.elapsed = 0;
    if (Math.abs(next.x - this.from.x) >= 0.5) this.facing = next.x > this.from.x ? 1 : -1;
  }

  /**
   * Advance by `dtMs` of wall clock at simulation `speed` — 0 freezes them
   * mid-stride with the clock, 4× makes them hustle. Returns whether the
   * pixel position actually moved, so the caller can skip a redraw.
   */
  step(dtMs: number, speed: number): boolean {
    if (this.dragging || !this.walking || dtMs <= 0 || speed <= 0) return false;
    const startX = this.x;
    const startY = this.y;
    let remaining = dtMs * speed;
    // One frame can swallow several short hops; the guard is for a pathological
    // dt (a backgrounded tab handing us a whole second), not for correctness.
    let guard = 0;
    while (remaining > 0 && this.walking && guard++ < 256) {
      if (!this.from || !this.to) {
        this.beginHop();
        continue;
      }
      if (this.hopMs <= 0) {
        this.x = this.to.x;
        this.y = this.to.y;
        this.beginHop();
        continue;
      }
      this.elapsed += remaining;
      if (this.elapsed >= this.hopMs) {
        remaining = this.elapsed - this.hopMs;
        this.x = this.to.x;
        this.y = this.to.y;
        this.beginHop();
      } else {
        const t = ease(this.elapsed / this.hopMs);
        this.x = this.from.x + (this.to.x - this.from.x) * t;
        this.y = this.from.y + (this.to.y - this.from.y) * t;
        remaining = 0;
      }
    }
    return this.x !== startX || this.y !== startY;
  }
}

