arguments.content:
/**
 * Who is allowed to repaint the floor, and when.
 *
 * The scene repaints by destroying every game object and rebuilding it, which
 * is fine for a state change and fatal for a drag: the token under the
 * player's finger is one of the objects destroyed, so a tick landing mid-drag
 * yanks the worker out of their hand and drops them back on their old station.
 * This gate is the whole fix — while a drag is open, paints are held rather
 * than run, and the drag's own end replays the last one that was owed.
 *
 * "Owed" is deliberately a single bit, not a count: what a held paint owes is
 * one repaint from current state, and ten held paints owe exactly the same
 * one. A resize clears the bit outright, because a resize repaints from
 * scratch by itself — see `mountRestaurantArenaScene`, which reboots the whole
 * game for one — and a dragend arriving after that has nothing left to replay.
 */
export class RepaintGate {
  private dragging = false;
  private owed = false;

  /** True while a drag is open (between `beginDrag()` and `endDrag()`/`resize()`). */
  get isDragging(): boolean {
    return this.dragging;
  }

  beginDrag(): void {
    this.dragging = true;
  }

  /**
   * Paints immediately (returns true) unless a drag is open, in which case the
   * paint is held back (returns false) and one repaint becomes owed.
   */
  requestPaint(): boolean {
    if (!this.dragging) return true;
    this.owed = true;
    return false;
  }

  /**
   * Ends the drag. Returns whether a repaint was held back during it — and so
   * needs replaying by the caller now.
   */
  endDrag(): boolean {
    const owed = this.owed;
    this.dragging = false;
    this.owed = false;
    return owed;
  }

  /**
   * Drops any open drag and clears anything owed, since the resize itself
   * repaints from scratch.
   */
  resize(): void {
    this.dragging = false;
    this.owed = false;
  }
}

