arguments.new_string:
private readonly outcomeToastMs = 2600;
/**
 * `restaurantArenaLayout(...).scale` for the paint in progress. Every font
 * size and text-adjacent offset in this file is authored at the 520×740
 * baseline and passed through `fs`/`sp` below, so a desktop window gets
 * bigger type in a bigger room rather than baseline-sized type marooned in
 * one — and a small window (`compact`, scale 1) is left exactly as it was.
 */
private layoutScale = 1;
/** Rounds a design size into the pixel string Phaser wants, grown to fit. */
private fs(px: number): string {
  return `${Math.round(px * this.layoutScale * 10) / 10}px`;
}
/**
 * A baseline-authored offset in this paint's pixels. Anything that positions
 * text relative to other text has to grow with `fs` or the two collide.
 */
private sp(px: number): number {
  return Math.round(px * this.layoutScale);
}

