private workerStatuses = new Map<Role, RestaurantArenaWorkerStatus>();
private readonly staffTokens = new Map<Role, Phaser.GameObjects.Container>();
/**
 * One walker per worker, outliving the repaints. The tokens are destroyed and
 * rebuilt on every paint; where each worker actually *is* — mid-stride
 * between the pass and the door, say — is not something a repaint may reset,
 * so it lives out here and the tokens are drawn at whatever it says.
 */
private readonly walkers = new Map<Role, StaffWalker>();
/** Held paints, so a tick mid-drag cannot yank the token out of the hand. */
private readonly repaintGate = new RepaintGate();
/** The worker currently in the player's hand, if any. */
private drag?: { role: Role; from: Location };
/** The layout the objects on screen were built from. */
private layout?: RestaurantArenaLayout;

