/**
 * A repaint *request*. Everything that changes state comes through here, and
 * while the player is dragging a worker it is answered with "later": a paint
 * destroys every object on screen, including the token under their finger.
 * The gate remembers that one is owed and `endDrag` replays it.
 */
private paint(): void {
  if (this.repaintGate.requestPaint()) this.repaintNow();
}

/**
 * The canvas box changed under us. The reboot that follows a real resize
 * paints from scratch, so nothing here is owed one — but a drag in flight is
 * over, and a `dragend` still to arrive from it must not replay a paint
 * against a layout that no longer exists.
 */
resize(): void {
  this.repaintGate.resize();
  this.drag = undefined;
  for (const walker of this.walkers.values()) walker.dragging = false;
}

private repaintNow(): void {
  this.tweens.killAll();
  this.children.removeAll(true);
  this.staffTokens.clear();
  const width = Math.max(320, this.cssWidth);
  const height = Math.max(240, this.cssHeight);
  const layout = restaurantArenaLayout(width, height);
  this.layout = layout;
  this.layoutScale = layout.scale;
  const g = this.add.graphics();

