private stackedSlot(location: Location, offset: number, layout: RestaurantArenaLayout): Point {
  const compact = layout.compact;
  const slot = layout.waypoints[location];
  return { x: slot.x + offset * (compact ? 17 : this.sp(22)), y: slot.y };
}

/**
 * `layout.waypoints` with one worker's own resting slot substituted in, so a
 * walk ends on the spot they will actually stand on rather than on top of a
 * colleague already at that station.
 */
private slotsFor(location: Location, slot: Point, layout: RestaurantArenaLayout): Record<Location, Point> {
  return { ...layout.waypoints, [location]: slot };
}

private drawWorkers(layout: RestaurantArenaLayout): void {
  const compact = layout.compact;
  const offsets = new Map<Location, number>();
  this.staffTokens.clear();
  const present = new Set<Role>();

  for (const worker of this.state.workers) {
    const location = this.visualLocation(worker);
    const offset = offsets.get(location) ?? 0;
    offsets.set(location, offset + 1);
    const slot = this.stackedSlot(location, offset, layout);
    present.add(worker.role);

    // The walker, not this paint, decides where the token goes: a worker
    // halfway to the door stays halfway to the door across a repaint, and a
    // worker whose station just changed starts walking to the new one.
    let walker = this.walkers.get(worker.role);
    if (!walker) {
      walker = new StaffWalker(location, slot);
      this.walkers.set(worker.role, walker);
    } else if (walker.dragging) {
      // The pointer owns the position until they are put down.
    } else if (walker.node !== location) {
      walker.setTarget(location, this.slotsFor(location, slot, layout), layout.spineY);
    } else if (!walker.walking) {
      // Same station, new geometry (a resize, or a colleague arriving next to
      // them): stand on the slot this layout gives them.
      walker.snap(slot, location);
    }

    const token = this.buildAvatar(walker.x, walker.y, worker.role, worker.load, compact);
    this.staffTokens.set(worker.role, token);
    this.faceToken(token, walker.facing);
    if (walker.walking || walker.dragging) this.tweens.killTweensOf(token);
    if (walker.dragging) token.setDepth(80);
    const heldHost = worker.role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
    const status = heldHost ? "acting" : (this.workerStatuses.get(worker.role) ?? this.workerStatus(worker));
    this.drawWorkerBadge(token, status, compact, heldHost);
    this.drawSpeechBubble(token, worker.role, compact);
    this.makeDraggable(token, worker.role, location, layout);
  }

  for (const role of [...this.walkers.keys()]) {
    if (!present.has(role)) this.walkers.delete(role);
  }
}

/** Mirror the figure so a worker faces the way they are walking. */
private faceToken(token: Phaser.GameObjects.Container, facing: 1 | -1): void {
  const figure = token.getByName("figure") as Phaser.GameObjects.Container | null;
  figure?.setScale(facing, 1);
}

// ── Dragging staff between stations ──────────────────────────────────

/**
 * Pick a worker up and put them down somewhere else: the direct way to say
 * "you, on the door" without hunting for a control that means it. The drop
 * dispatches the same `assign_<role>_<location>` action the engine takes from
 * anywhere else, so a drag is a normal player action with a normal receipt in
 * the log — it just reads as moving a person.
 */
private makeDraggable(
  token: Phaser.GameObjects.Container,
  role: Role,
  from: Location,
  layout: RestaurantArenaLayout,
): void {
  const grab = layout.compact ? 22 : this.sp(28);
  token.setSize(grab, grab);
  token.setInteractive(
    new Phaser.Geom.Rectangle(-grab / 2, -grab / 2, grab, grab),
    Phaser.Geom.Rectangle.Contains,
  );
  this.input.setDraggable(token);

  token.on("dragstart", () => {
    const walker = this.walkers.get(role);
    if (walker) walker.dragging = true;
    this.drag = { role, from };
    this.repaintGate.beginDrag();
    this.tweens.killTweensOf(token);
    token.setDepth(80);
    this.game.canvas.style.cursor = "grabbing";
  });

  token.on("drag", (_pointer: Phaser.Input.Pointer, dragX: number, dragY: number) => {
    token.setPosition(dragX, dragY);
    const walker = this.walkers.get(role);
    if (!walker) return;
    if (Math.abs(dragX - walker.x) >= 0.5) walker.facing = dragX > walker.x ? 1 : -1;
    walker.x = dragX;
    walker.y = dragY;
    this.faceToken(token, walker.facing);
  });

  token.on("dragend", () => {
    this.game.canvas.style.cursor = "";
    const dropped = arenaLocationAt(layout, token.x, token.y);
    const walker = this.walkers.get(role);
    if (walker) walker.dragging = false;
    const moved = Boolean(dropped) && dropped !== from;
    // Land them on the new station before the repaint rather than after the
    // engine answers, so the token stays where it was put instead of
    // snapping home for a frame and walking back.
    if (walker && dropped) walker.snap(this.slotFor(dropped, layout, role), dropped);
    else if (walker) walker.snap(this.slotFor(from, layout, role), from);
    this.drag = undefined;
    const owed = this.repaintGate.endDrag();
    if (moved && dropped) this.onAction(`assign_${role}_${dropped}`);
    else if (owed) this.paint();
    else this.repaintNow();
  });
}

/**
 * Where a worker stands at `location` right now — behind whoever is already
 * there. Used on a drop, before the engine has confirmed the move, so the
 * dropped worker is counted at their destination and not at their old post.
 */
private slotFor(location: Location, layout: RestaurantArenaLayout, role: Role): Point {
  let offset = 0;
  for (const worker of this.state.workers) {
    if (worker.role === role) continue;
    if (this.visualLocation(worker) === location) offset += 1;
  }
  return this.stackedSlot(location, offset, layout);
}

/**
 * Walk everyone one frame closer to where they are meant to be. Only the
 * tokens that actually moved are touched — a still floor costs nothing — and
 * the sim's own speed drives it, so pause freezes staff mid-stride and 4×
 * makes them hustle.
 */
update(_time: number, delta: number): void {
  const speed = this.running ? (this.state.sim?.speed ?? 1) : 0;
  const spineY = this.layout?.spineY ?? 0;
  void spineY;
  for (const [role, walker] of this.walkers) {
    if (walker.dragging) continue;
    const wasWalking = walker.walking;
    if (!walker.step(delta, speed)) continue;
    const token = this.staffTokens.get(role);
    if (!token) continue;
    token.setPosition(walker.x, walker.y);
    this.faceToken(token, walker.facing);
    // Arrived: hand the token back to the idle bob it was taken from.
    if (wasWalking && !walker.walking) this.startIdleBob(token, walker.y, role);
  }
}

