arguments.new_string:
token.on("dragend", () => {
  this.game.canvas.style.cursor = "";
  // Dropped on the ink around the floor: they go back to their own post.
  const dropped = arenaLocationAt(layout, token.x, token.y) ?? from;
  const walker = this.walkers.get(role);
  if (walker) {
    walker.dragging = false;
    // Stand them on the destination before anything repaints, so the token
    // stays where it was put instead of blinking home for a frame and
    // walking back once the engine answers.
    walker.snap(this.slotFor(dropped, layout, role), dropped);
  }
  // Dispatched while the gate is still closed on purpose: the state the
  // engine answers with is held like any other mid-drag paint, and the
  // endDrag() below is what releases it.
  if (dropped !== from) this.onAction(`assign_${role}_${dropped}`);
  this.repaintGate.endDrag();
  // A drop always changes the picture — the token's depth, its idle bob,
  // the worker's station — so it repaints whether or not one was held.
  this.repaintNow();
});

