  from: Location,
  layout: RestaurantArenaLayout,
): void {
  const grab = layout.compact ? 22 : this.sp(28);
  token.setSize(grab, grab);
  token.setInteractive(
    new Phaser.Geom.Rectangle(-grab / 2, -grab / 2, grab, grab),
    Phaser.Geom.Rectangle.Contains,
  );
  this.input.setDraggable(token);

  token.on("dragstart", () => {
    const walker = this.walkers.get(role);
    if (walker) walker.dragging = true;
    this.drag = { role, from };
    this.repaintGate.beginDrag();
    this.tweens.killTweensOf(token);
    token.setDepth(80);
    this.game.canvas.style.cursor = "grabbing";
  });

  token.on("drag", (_pointer: Phaser.Input.Pointer, dragX: number, dragY: number) => {
    token.setPosition(dragX, dragY);
    const walker = this.walkers.get(role);
    if (!walker) return;
    if (Math.abs(dragX - walker.x) >= 0.5) walker.facing = dragX > walker.x ? 1 : -1;
    walker.x = dragX;
    walker.y = dragY;
    this.faceToken(token, walker.facing);
  });

