875	  /** Ticket rail: every live order as a card you can click to rush. */
876	  private drawTickets(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
877	    const zone = layout.tickets;
878	    const compact = layout.compact;
879	    g.fillStyle(COLORS.panel);
880	    g.fillRoundedRect(zone.x, zone.y, zone.width, zone.height, 4);
881	    this.add.text(zone.x + 6, zone.y + 4, "TICKETS", {
882	      color: "#f2cc5c",
883	      fontFamily: "Arial Narrow, sans-serif",
884	      fontSize: compact ? this.fs(7) : this.fs(9),
885	      fontStyle: "bold",
886	    });
887	
888	    const live = this.state.orders.filter((order) => order.status !== "served" && order.status !== "cancelled");
889	    const top = zone.y + (compact ? 14 : 17);
890	    const cardHeight = zone.height - (top - zone.y) - 4;
891	
892	    if (live.length === 0) {
893	      this.add
894	        .text(zone.x + zone.width / 2, top + cardHeight / 2, "No tickets", {
895	          color: "#8d8378",
896	          fontFamily: MONO,
897	          fontSize: compact ? this.fs(7) : this.fs(9),
898	        })
899	        .setOrigin(0.5);
900	      return;
901	    }
902	
903	    const gap = 4;
904	    const maxCards = Math.max(1, Math.min(live.length, Math.floor((zone.width - 8) / (compact ? 74 : 92))));
905	    const cardWidth = (zone.width - 8 - gap * (maxCards - 1)) / maxCards;
906	
907	    live.slice(0, maxCards).forEach((order, index) => {
908	      const x = zone.x + 4 + index * (cardWidth + gap);
909	      const rect = { x, y: top, width: cardWidth, height: cardHeight };
910	      g.fillStyle(COLORS.ticket);
911	      g.fillRoundedRect(x, top, cardWidth, cardHeight, 3);
912	      if (order.priority === "high") {
913	        g.lineStyle(2, COLORS.alert, 0.9);
914	        g.strokeRoundedRect(x, top, cardWidth, cardHeight, 3);
915	      }
916	
917	      const table = (order.tableId ?? order.id).replace("table-", "T").replace(/order-x?/, "#");
918	      this.add.text(x + 4, top + 3, table, {
919	        color: "#2b2118",
920	        fontFamily: MONO,
921	        fontSize: compact ? this.fs(8) : this.fs(10),
922	        fontStyle: "bold",
923	      });
924	      this.add
925	        .text(x + cardWidth - 4, top + 3, order.status.toUpperCase(), {
926	          color: "#ffffff",
927	          backgroundColor: hex(STATUS_COLORS[order.status]),
928	          fontFamily: MONO,
929	          fontSize: compact ? this.fs(5) : this.fs(6),
930	          fontStyle: "bold",
931	          padding: { x: 2, y: 1 },
932	        })
933	        .setOrigin(1, 0);
934	      this.add.text(x + 4, top + (compact ? 15 : 19), order.items.join(" + ") || "—", {
935	        color: "#4f4136",
936	        fontFamily: MONO,
937	        fontSize: compact ? this.fs(6) : this.fs(8),
938	      });
939	
940	      if (order.allergy) {
941	        this.add
942	          .text(x + 4, top + cardHeight - 3, `${order.allergy.toUpperCase()} ALLERGY`, {
943	            color: "#ffffff",
944	            backgroundColor: "#c73535",
945	            fontFamily: MONO,
946	            fontSize: compact ? this.fs(5) : this.fs(6),
947	            fontStyle: "bold",
948	            padding: { x: 2, y: 1 },
949	          })
950	          .setOrigin(0, 1);
951	      } else if (order.priority === "high") {
952	        this.add
953	          .text(x + 4, top + cardHeight - 3, "RUSHED", {
954	            color: "#ffffff",
955	            backgroundColor: "#e08b2c",
956	            fontFamily: MONO,
957	            fontSize: compact ? this.fs(5) : this.fs(6),
958	            fontStyle: "bold",
959	            padding: { x: 2, y: 1 },
960	          })
961	          .setOrigin(0, 1);
962	      }
963	
964	      const tableIndex = Number((order.tableId?.match(/\d+/) ?? ["0"])[0]);
965	      if (order.priority !== "high" && tableIndex >= 1 && tableIndex <= 3) {
966	        this.hotspot(rect, `rush_table_${tableIndex}`, "Rush this ticket");
967	      } else if (order.allergy) {
968	        this.hotspot(rect, "prioritize_allergy", "Prioritize allergy ticket");
969	      }
970	    });
971	
972	    if (live.length > maxCards) {
973	      this.add
974	        .text(zone.x + zone.width - 5, zone.y + 5, `+${live.length - maxCards}`, {
975	          color: "#f2cc5c",
976	          fontFamily: MONO,
977	          fontSize: compact ? this.fs(6) : this.fs(8),
978	          fontStyle: "bold",
979	        })
980	        .setOrigin(1, 0);
981	    }
982	  }
983	
984	  /**
985	   * The service log. Watching the staff think is what makes their behaviour
986	   * legible — and a legible floor is what makes the player's calls informed.
987	   */
988	  private drawFeed(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
989	    const zone = layout.feed;
990	    const compact = layout.compact;
991	    g.fillStyle(COLORS.panel);
992	    g.fillRoundedRect(zone.x, zone.y, zone.width, zone.height, 4);
993	    this.add.text(zone.x + 6, zone.y + 4, "EVENT FEED", {
994	      color: "#f2cc5c",
995	      fontFamily: "Arial Narrow, sans-serif",
996	      fontSize: compact ? this.fs(7) : this.fs(9),
997	      fontStyle: "bold",
998	    });
999	
1000	    // Keep the narrative spine visible while the activity log scrolls past it.
1001	    // This is deliberately fixed-order UI, not inferred from whichever feed
1002	    // entries happen to be in the tail of a long shift.
1003	    const milestoneTop = zone.y + (compact ? 14 : 18);
1004	    const milestone = this.add.text(zone.x + 6, milestoneTop, milestoneFeedText(), {
1005	      color: "#c9bdae",
1006	      fontFamily: MONO,
1007	      fontSize: compact ? this.fs(5) : this.fs(6),
1008	      fontStyle: "bold",
1009	      wordWrap: { width: zone.width - 12 },
1010	      maxLines: layout.feedBeside ? 2 : 1,
1011	      lineSpacing: compact ? 1 : 2,
1012	    });
1013	    void milestone;
1014	
1015	    const entries = this.state.feed ?? [];
1016	    const top = milestoneTop + milestone.height + (compact ? 2 : 4);
1017	    // The side rail is narrow but tall, so entries there get a second line
1018	    // rather than being cut off mid-sentence.
1019	    const bodyLines = layout.feedBeside ? 2 : 1;
1020	    const lineHeight = (compact ? 15 : 18) + (bodyLines - 1) * (compact ? 7 : 9);
1021	    const rows = Math.max(1, Math.floor((zone.height - (top - zone.y) - 2) / lineHeight));
1022	    const shown = entries.slice(-rows);
1023	
1024	    if (shown.length === 0) {
1025	      this.add.text(zone.x + 6, top + 2, "Press Play to open.", {
1026	        color: "#8d8378",
1027	        fontFamily: MONO,
1028	        fontSize: compact ? this.fs(7) : this.fs(9),
1029	      });
1030	      return;
1031	    }
1032	
1033	    shown.forEach((entry, index) => {
1034	      const y = top + index * lineHeight;
1035	      const color = VOICE_COLORS[entry.voice] ?? "#c9bdae";
1036	      // The player's own calls get a left accent rule and full-strength body
1037	      // text, so "what I decided" separates from "what the staff said" at a
1038	      // glance rather than only by reading the name (#304). The feed is the
1039	      // record of the shift; a manager scanning it back should be able to
1040	      // find their own decisions without parsing every line.
1041	      const mine = entry.voice === "you";
1042	      const textX = zone.x + 6 + (mine ? 4 : 0);
1043	      if (mine) {
1044	        g.fillStyle(0x7ddc9f);
1045	        g.fillRoundedRect(zone.x + 3, y, 2, lineHeight - (compact ? 3 : 4), 1);
1046	      }
1047	      const head = this.add.text(textX, y, `${entry.clock} ${entry.who}`, {
1048	        color,
1049	        fontFamily: MONO,
1050	        fontSize: compact ? this.fs(6) : this.fs(7),
1051	        fontStyle: "bold",
1052	      });
1053	      this.add.text(textX, y + (compact ? 7 : 8), entry.text, {
1054	        color: entry.kind === "thought" ? "#9a8f82" : mine ? "#fff3d6" : "#e8ddcc",
1055	        fontFamily: MONO,
1056	        fontSize: compact ? this.fs(6) : this.fs(8),
1057	        fontStyle: entry.kind === "thought" ? "italic" : "normal",
1058	        wordWrap: { width: zone.width - 12 - (mine ? 4 : 0) },
1059	        maxLines: bodyLines,
1060	      });
1061	      void head;
1062	    });
1063	  }
