/** How long one straight hop takes at `WALK_SPEED_PX_PER_SEC`. */
export function hopDurationMs(from: Point, to: Point): number {
  const distance = Math.hypot(to.x - from.x, to.y - from.y);
  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
}

/**
 * Ease each hop rather than the whole walk: a worker leans into a leg of the
 * corridor and settles out of it, and the corners between legs stay crisp
 * instead of the whole trip sliding as one long glide.
 */
function ease(t: number): number {
  return t * t * (3 - 2 * t);
}

export class StaffWalker {
  x: number;
  y: number;
  facing: 1 | -1 = 1;
  walking = false;
  /** The player has this worker picked up; the pointer owns the position. */
  dragging = false;
  /** Where they belong — set the moment a walk starts, not when it ends. */
  node: WalkNode;

  private hops: Point[] = [];
  private from?: Point;
  private to?: Point;
  private hopMs = 0;
  private elapsed = 0;

  constructor(node: WalkNode, slot: Point) {
    this.node = node;
    this.x = slot.x;
    this.y = slot.y;
  }

  /** Teleport onto `slot`/`node` with no walk in progress (e.g. after a drop). */
  snap(slot: Point, node: WalkNode): void {
    this.x = slot.x;
    this.y = slot.y;
    this.node = node;
    this.walking = false;
    this.hops = [];
    this.from = undefined;
    this.to = undefined;
    this.hopMs = 0;
    this.elapsed = 0;
  }

  /** Walk to `target` from wherever they are standing, along the hallway. */
  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
    const slot = waypoints[target];
    if (!slot) return;
    const route = corridorPoints({ x: this.x, y: this.y }, bfsPath(this.node, target), waypoints, spineY);
    this.node = target;
    // The first point is the pixel they are already standing on.
    this.hops = route.slice(1);
    this.from = undefined;
    this.to = undefined;
    this.hopMs = 0;
    this.elapsed = 0;
    this.walking = this.hops.length > 0;
    if (this.walking) this.beginHop();
  }

  private beginHop(): void {
    const next = this.hops.shift();
    if (!next) {
      this.walking = false;
      this.from = undefined;
      this.to = undefined;
      return;
    }
    this.from = { x: this.x, y: this.y };
    this.to = next;
    this.hopMs = hopDurationMs(this.from, this.to);
    this.elapsed = 0;
    if (Math.abs(next.x - this.from.x) >= 0.5) this.facing = next.x > this.from.x ? 1 : -1;
  }

  /**
   * Advance by `dtMs` of wall clock at simulation `speed` — 0 freezes them
   * mid-stride with the clock, 4× makes them hustle. Returns whether the
   * pixel position actually moved, so the caller can skip a redraw.
   */
  step(dtMs: number, speed: number): boolean {
    if (this.dragging || !this.walking || dtMs <= 0 || speed <= 0) return false;
    const startX = this.x;
    const startY = this.y;
    let remaining = dtMs * speed;
    // One frame can swallow several short hops; the guard is for a pathological
    // dt (a backgrounded tab handing us a whole second), not for correctness.
    let guard = 0;
    while (remaining > 0 && this.walking && guard++ < 256) {
      if (!this.from || !this.to) {
        this.beginHop();
        continue;
      }
      if (this.hopMs <= 0) {
        this.x = this.to.x;
        this.y = this.to.y;
        this.beginHop();
        continue;
      }
      this.elapsed += remaining;
      if (this.elapsed >= this.hopMs) {
        remaining = this.elapsed - this.hopMs;
        this.x = this.to.x;
        this.y = this.to.y;
        this.beginHop();
      } else {
        const t = ease(this.elapsed / this.hopMs);
        this.x = this.from.x + (this.to.x - this.from.x) * t;
        this.y = this.from.y + (this.to.y - this.from.y) * t;
        remaining = 0;
      }
    }
    return this.x !== startX || this.y !== startY;
  }
}

