function inside(rect: ArenaRect, x: number, y: number): boolean {
  return x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height;
}

/**
 * Which station a pixel belongs to, or `undefined` for the ink around the
 * floor. Used to turn "let go of a worker here" into a station to assign
 * them to; the stand is checked first because it overlaps the door zone.
 */
export function arenaLocationAt(
  layout: RestaurantArenaLayout,
  x: number,
  y: number,
): ArenaLocation | undefined {
  if (inside(layout.doorStand, x, y) || inside(layout.door, x, y)) return "queue";
  if (inside(layout.kitchen, x, y)) return "kitchen";
  if (inside(layout.pass, x, y)) return "pass";
  if (inside(layout.dining, x, y)) return "floor";
  return undefined;
}

