    expect(restaurantArenaLayout(BASE_WIDTH * 2, BASE_HEIGHT).scale).toBe(1);
    expect(restaurantArenaLayout(BASE_WIDTH, BASE_HEIGHT * 2).scale).toBe(1);
    expect(restaurantArenaLayout(BASE_WIDTH * 1.5, BASE_HEIGHT * 1.5).scale).toBeCloseTo(1.5, 5);
    // Tighter axis wins even when the other is enormous.
    expect(restaurantArenaLayout(BASE_WIDTH * 3, BASE_HEIGHT * 1.25).scale).toBeCloseTo(1.25, 5);
  });

  test("never shrinks below baseline, and stops growing near 1.9", () => {
    expect(restaurantArenaLayout(BASE_WIDTH / 2, BASE_HEIGHT / 2).scale).toBe(1);
    expect(restaurantArenaLayout(BASE_WIDTH * 4, BASE_HEIGHT * 4).scale).toBe(MAX_SCALE);
    expect(restaurantArenaLayout(9000, 9000).scale).toBe(MAX_SCALE);
    for (const [w, h] of SIZES) {
      const { scale } = restaurantArenaLayout(w, h);
      expect(scale).toBeGreaterThanOrEqual(1);
      expect(scale).toBeLessThanOrEqual(MAX_SCALE);
    }
  });

  test("packs tight and stops growing text below either compact threshold", () => {
    const narrow = restaurantArenaLayout(COMPACT_WIDTH - 1, 4000);
    expect(narrow.compact).toBe(true);
    // Compact is the whole point: a squeezed window must not also scale type up.
    expect(narrow.scale).toBe(1);

    const short = restaurantArenaLayout(4000, COMPACT_HEIGHT - 1);
    expect(short.compact).toBe(true);
    expect(short.scale).toBe(1);

    expect(restaurantArenaLayout(COMPACT_WIDTH, COMPACT_HEIGHT).compact).toBe(false);
  });

  test("moves the service log beside the floor once there is width for a rail", () => {
    expect(restaurantArenaLayout(FEED_BESIDE_WIDTH - 1, 800).feedBeside).toBe(false);
    expect(restaurantArenaLayout(FEED_BESIDE_WIDTH, 800).feedBeside).toBe(true);

    const beside = restaurantArenaLayout(900, 800);
    expect(beside.feedBeside).toBe(true);
    // Beside means a column to the right of the room, not a strip under it.
    expect(beside.feed.x).toBeGreaterThanOrEqual(beside.dining.x + beside.dining.width);

    const below = restaurantArenaLayout(520, 800);
    expect(below.feed.y).toBeGreaterThanOrEqual(below.dining.y + below.dining.height);
  });

  test("keeps every rect inside the window it was measured for", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      for (const [name, rect] of rects(layout)) {
        const where = `${name} at ${w}x${h}`;
        expect(rect.x, where).toBeGreaterThanOrEqual(0);
        expect(rect.y, where).toBeGreaterThanOrEqual(0);
        expect(rect.width, where).toBeGreaterThanOrEqual(0);
        expect(rect.height, where).toBeGreaterThanOrEqual(0);
        expect(rect.x + rect.width, where).toBeLessThanOrEqual(w);
        expect(rect.y + rect.height, where).toBeLessThanOrEqual(h);
      }
      for (const [name, point] of Object.entries(layout.waypoints)) {
        const where = `waypoint ${name} at ${w}x${h}`;
        expect(point.x, where).toBeGreaterThanOrEqual(0);
        expect(point.x, where).toBeLessThanOrEqual(w);
        expect(point.y, where).toBeGreaterThanOrEqual(0);
        expect(point.y, where).toBeLessThanOrEqual(h);
      }
    }
  });

  test("keeps the host stand a usable click target at any size", () => {
    for (const [w, h] of SIZES) {
      if (w < MIN_STAND_WIDTH || h < MIN_STAND_HEIGHT) continue;
      const { doorStand } = restaurantArenaLayout(w, h);
      expect(doorStand.width, `stand width at ${w}x${h}`).toBeGreaterThanOrEqual(MIN_STAND_WIDTH);
      expect(doorStand.height, `stand height at ${w}x${h}`).toBeGreaterThanOrEqual(MIN_STAND_HEIGHT);
    }
  });

  test("stands the host inside their own doorway", () => {
    for (const [w, h] of SIZES) {
      if (w < 320 || h < 240) continue;
      const layout = restaurantArenaLayout(w, h);
      expect(contains(layout.door, layout.doorStand), `stand in door at ${w}x${h}`).toBe(true);
    }
  });

  test("runs the hallway line through the pass zone", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      const where = `spineY at ${w}x${h}`;
      expect(layout.spineY, where).toBeGreaterThanOrEqual(layout.pass.y);
      expect(layout.spineY, where).toBeLessThanOrEqual(layout.pass.y + layout.pass.height);
    }
  });

  test("lays the room out left to right: kitchen, pass, dining, door", () => {
    const layout = restaurantArenaLayout(1200, 900);
    expect(layout.pass.x).toBeGreaterThanOrEqual(layout.kitchen.x + layout.kitchen.width - 1);
    expect(layout.dining.x).toBeGreaterThanOrEqual(layout.pass.x + layout.pass.width - 1);
    expect(contains(layout.dining, layout.door)).toBe(true);
    expect(layout.brief.y).toBeGreaterThanOrEqual(layout.topBar.y + layout.topBar.height);
    expect(layout.kitchen.y).toBeGreaterThanOrEqual(layout.brief.y + layout.brief.height);
  });

  test("parks each waypoint where that station's worker should stand", () => {
    for (const [w, h] of SIZES) {
      if (w < 320 || h < 240) continue;
      const layout = restaurantArenaLayout(w, h);
      const where = `at ${w}x${h}`;
      expect(holds(layout.kitchen, layout.waypoints.kitchen), `kitchen ${where}`).toBe(true);
      expect(holds(layout.pass, layout.waypoints.pass), `pass ${where}`).toBe(true);
      // The floor waypoint is the dining-room resting slot, not the door.
      expect(holds(layout.dining, layout.waypoints.floor), `floor ${where}`).toBe(true);
      // The queue waypoint sits on the host stand itself.
      expect(holds(layout.doorStand, layout.waypoints.queue), `queue ${where}`).toBe(true);
      // The pass waypoint rides the hallway, so a walk through it needs no detour.
      expect(layout.waypoints.pass.y, `pass on spine ${where}`).toBe(layout.spineY);
    }
  });

  test("reports integer geometry, so nothing lands on a half pixel", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      for (const [name, rect] of rects(layout)) {
        for (const [field, value] of Object.entries(rect)) {
          expect(Number.isInteger(value), `${name}.${field} at ${w}x${h} = ${value}`).toBe(true);
        }
      }
      expect(Number.isInteger(layout.spineY)).toBe(true);
    }
  });

  test("survives a garbage measurement instead of emitting NaN rects", () => {
    for (const [w, h] of [
      [-100, -100],
      [Number.NaN, Number.NaN],
    ] as [number, number][]) {
      const layout = restaurantArenaLayout(w, h);
      for (const [name, rect] of rects(layout)) {
        for (const [field, value] of Object.entries(rect)) {
          expect(Number.isFinite(value), `${name}.${field}`).toBe(true);
        }
      }
      expect(Number.isFinite(layout.spineY)).toBe(true);
    }
  });
});

describe("arenaLocationAt", () => {
  const layout = restaurantArenaLayout(900, 800);

  test("names the station under a dropped worker", () => {
    const centre = (rect: ArenaRect) => ({ x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 });
    expect(arenaLocationAt(layout, centre(layout.kitchen).x, centre(layout.kitchen).y)).toBe("kitchen");
    expect(arenaLocationAt(layout, centre(layout.pass).x, centre(layout.pass).y)).toBe("pass");
    expect(arenaLocationAt(layout, centre(layout.doorStand).x, centre(layout.doorStand).y)).toBe("queue");
    // The door zone lives inside the dining room; dropping there means the door.
    expect(arenaLocationAt(layout, centre(layout.door).x, centre(layout.door).y)).toBe("queue");
  });

  test("reads the dining room outside the doorway as the floor", () => {
    expect(arenaLocationAt(layout, layout.waypoints.floor.x, layout.waypoints.floor.y)).toBe("floor");
  });

  test("returns nothing for the ink around the floor", () => {
    expect(arenaLocationAt(layout, layout.topBar.x + 2, layout.topBar.y + 2)).toBeUndefined();
    expect(arenaLocationAt(layout, -50, -50)).toBeUndefined();
  });
});

