import { describe, expect, test } from "bun:test";
import { restaurantArenaLayout } from "./restaurant-arena-layout.js";
import {
  bfsPath,
  corridorPoints,
  hopDurationMs,
  StaffWalker,
  WALK_GRAPH,
  WALK_SPEED_PX_PER_SEC,
  type Point,
  type WalkNode,
} from "./staff-walk.js";

const layout = restaurantArenaLayout(900, 800);
const waypoints = layout.waypoints;
const spineY = layout.spineY;

const NODES: WalkNode[] = ["kitchen", "pass", "floor", "queue"];

function totalLength(points: readonly Point[]): number {
  let sum = 0;
  for (let i = 1; i < points.length; i++) {
    sum += Math.hypot(points[i]!.x - points[i - 1]!.x, points[i]!.y - points[i - 1]!.y);
  }
  return sum;
}

describe("WALK_GRAPH", () => {
  test("is one hallway, not a set of doors that all open onto each other", () => {
    expect(WALK_GRAPH).toEqual({
      kitchen: ["pass"],
      pass: ["kitchen", "floor"],
      floor: ["pass", "queue"],
      queue: ["floor"],
    });
  });

  test("is symmetric, because a corridor you can walk down you can walk back up", () => {
    for (const node of NODES) {
      for (const neighbour of WALK_GRAPH[node]) {
        expect(WALK_GRAPH[neighbour], `${neighbour} -> ${node}`).toContain(node);
      }
    }
  });
});

describe("bfsPath", () => {
  test("routes the kitchen to the queue through both through-stations", () => {
    expect(bfsPath("kitchen", "queue")).toEqual(["kitchen", "pass", "floor", "queue"]);
    expect(bfsPath("queue", "kitchen")).toEqual(["queue", "floor", "pass", "kitchen"]);
  });

  test("includes both ends, so the route is walkable as returned", () => {
    expect(bfsPath("kitchen", "pass")).toEqual(["kitchen", "pass"]);
    expect(bfsPath("pass", "queue")).toEqual(["pass", "floor", "queue"]);
    expect(bfsPath("floor", "kitchen")).toEqual(["floor", "pass", "kitchen"]);
  });

  test("standing still is a route of one station, not an empty one", () => {
    for (const node of NODES) expect(bfsPath(node, node)).toEqual([node]);
  });

  test("never invents a step the graph has no edge for", () => {
    for (const from of NODES) {
      for (const to of NODES) {
        const path = bfsPath(from, to);
        expect(path[0], `${from}->${to} start`).toBe(from);
        expect(path[path.length - 1], `${from}->${to} end`).toBe(to);
        for (let i = 1; i < path.length; i++) {
          expect(WALK_GRAPH[path[i - 1]!], `${from}->${to} leg ${i}`).toContain(path[i]!);
        }
        // No station is visited twice on a four-node line.
        expect(new Set(path).size).toBe(path.length);
      }
    }
  });
});

describe("corridorPoints", () => {
  test("starts on the pixel the worker is standing on", () => {
    const start = { x: 12, y: 34 };
    expect(corridorPoints(start, bfsPath("kitchen", "queue"), waypoints, spineY)[0]).toEqual(start);
  });

  test("moves in one axis at a time, so nobody cuts across the tables", () => {
    for (const from of NODES) {
