    while (walker.walking && frames++ < 10_000) walker.step(16, 1);

    expect(frames).toBeLessThan(10_000);
    expect(walker.walking).toBe(false);
    expect(walker.x).toBeCloseTo(waypoints.queue.x, 5);
    expect(walker.y).toBeCloseTo(waypoints.queue.y, 5);
  });

  test("takes about as long as the corridor is, at 200px/s", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    const expected = (totalLength(corridorPoints(waypoints.kitchen, bfsPath("kitchen", "queue"), waypoints, spineY)) /
      WALK_SPEED_PX_PER_SEC) *
      1000;

    let elapsed = 0;
    while (walker.walking && elapsed < 60_000) {
      walker.step(16, 1);
      elapsed += 16;
    }
    // Within a frame of the honest distance/speed answer.
    expect(elapsed).toBeGreaterThanOrEqual(expected);
    expect(elapsed).toBeLessThan(expected + 32);
  });

  test("eases each hop instead of gliding the whole trip at one speed", () => {
    const from: Point = { x: 0, y: 0 };
    const to: Point = { x: 400, y: 0 };
    const walker = new StaffWalker("kitchen", from);
    // A one-hop walk: same y, so the corridor is a single straight leg.
    walker.setTarget("pass", { ...waypoints, pass: to }, 0);

    walker.step(500, 1); // a quarter of a 2000ms hop
    const quarter = walker.x;
    walker.step(500, 1); // halfway
    const half = walker.x;

    // Eased: slow off the mark, so a quarter of the time is under a quarter of
    // the way, and the midpoint is still exactly the midpoint.
    expect(quarter).toBeLessThan(100);
    expect(quarter).toBeGreaterThan(0);
    expect(half).toBeCloseTo(200, 5);
    // Symmetric: the second quarter covers more ground than the first.
    expect(half - quarter).toBeGreaterThan(quarter);
  });

  test("turns to face the way it is walking", () => {
    const walker = new StaffWalker("queue", waypoints.queue);
    walker.setTarget("kitchen", waypoints, spineY);
    walker.step(16, 1);
    // The kitchen is stage left of the door.
    expect(walker.facing).toBe(-1);

    while (walker.walking) walker.step(16, 1);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(16, 1);
    expect(walker.facing).toBe(1);
  });

  test("freezes mid-stride when the simulation is paused", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(100, 1);
    const { x, y } = walker;

    expect(walker.step(1000, 0)).toBe(false);
    expect(walker.x).toBe(x);
    expect(walker.y).toBe(y);
    // Still on the way, just held.
    expect(walker.walking).toBe(true);

    expect(walker.step(100, 1)).toBe(true);
  });

  test("hustles at higher simulation speeds", () => {
    const slow = new StaffWalker("kitchen", waypoints.kitchen);
    const fast = new StaffWalker("kitchen", waypoints.kitchen);
    slow.setTarget("queue", waypoints, spineY);
    fast.setTarget("queue", waypoints, spineY);

    let slowFrames = 0;
    while (slow.walking && slowFrames++ < 10_000) slow.step(16, 1);
    let fastFrames = 0;
    while (fast.walking && fastFrames++ < 10_000) fast.step(16, 4);

    expect(fastFrames).toBeLessThan(slowFrames);
  });

  test("stands still while the player is holding it", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.dragging = true;

    expect(walker.step(1000, 1)).toBe(false);
    expect(walker.x).toBe(waypoints.kitchen.x);

    // Dropped back into the world: the walk it was on is still its walk.
    walker.dragging = false;
    expect(walker.step(16, 1)).toBe(true);
  });

  test("snap abandons the walk and takes the station with it", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(200, 1);

    walker.snap(waypoints.pass, "pass");
    expect(walker.node).toBe("pass");
    expect(walker.x).toBe(waypoints.pass.x);
    expect(walker.y).toBe(waypoints.pass.y);
    expect(walker.walking).toBe(false);
    // The old destination cannot reassert itself on the next frame.
    expect(walker.step(1000, 1)).toBe(false);
    expect(walker.x).toBe(waypoints.pass.x);
  });

  test("retargeting mid-walk turns around from where it stands, not from its old post", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(300, 1);
    const turnedAt = { x: walker.x, y: walker.y };

    walker.setTarget("kitchen", waypoints, spineY);
    expect(walker.node).toBe("kitchen");
    expect(walker.x).toBe(turnedAt.x);
    expect(walker.y).toBe(turnedAt.y);

    let frames = 0;
    while (walker.walking && frames++ < 10_000) walker.step(16, 1);
    expect(walker.x).toBeCloseTo(waypoints.kitchen.x, 5);
    expect(walker.y).toBeCloseTo(waypoints.kitchen.y, 5);
  });

  test("targeting the station it is already at is a no-op, not a lap of the room", () => {
    const walker = new StaffWalker("pass", waypoints.pass);
    walker.setTarget("pass", waypoints, spineY);
    expect(walker.walking).toBe(false);
    expect(walker.x).toBe(waypoints.pass.x);
    expect(walker.y).toBe(waypoints.pass.y);
  });

  test("swallows a monstrous frame delta without leaving the corridor", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    // A backgrounded tab handing us a whole minute at once.
    walker.step(60_000, 1);
    expect(walker.walking).toBe(false);
    expect(walker.x).toBeCloseTo(waypoints.queue.x, 5);
    expect(walker.y).toBeCloseTo(waypoints.queue.y, 5);
  });

  test("ignores a nonsense delta rather than drifting on it", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.step(0, 1)).toBe(false);
    expect(walker.step(-16, 1)).toBe(false);
    expect(walker.x).toBe(waypoints.kitchen.x);
  });

  test("stays on the corridor for every frame of the walk", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    const legs = corridorPoints(waypoints.kitchen, bfsPath("kitchen", "queue"), waypoints, spineY);

    let frames = 0;
    while (walker.walking && frames++ < 10_000) {
      walker.step(16, 1);
      // Every position sits on one of the axis-aligned legs of the route.
      const onALeg = legs.slice(1).some((to, i) => {
        const from = legs[i]!;
        const minX = Math.min(from.x, to.x) - 0.01;
        const maxX = Math.max(from.x, to.x) + 0.01;
        const minY = Math.min(from.y, to.y) - 0.01;
        const maxY = Math.max(from.y, to.y) + 0.01;
        return walker.x >= minX && walker.x <= maxX && walker.y >= minY && walker.y <= maxY;
      });
      expect(onALeg, `frame ${frames} at ${walker.x},${walker.y}`).toBe(true);
    }
  });
});

