import { describe, expect, test } from "bun:test";
import { RepaintGate } from "./restaurant-arena-repaint-gate.js";

/** The scene's side of the gate: count what actually reached the canvas. */
function scene() {
  const gate = new RepaintGate();
  let paints = 0;
  return {
    gate,
    get paints() {
      return paints;
    },
    /** What `RestaurantArenaScene.paint()` does. */
    paint() {
      if (gate.requestPaint()) paints++;
    },
    /** What the dragend handler does. */
    endDrag() {
      gate.endDrag();
      paints++;
    },
  };
}

describe("RepaintGate", () => {
  test("paints on request while nothing is being dragged", () => {
    const gate = new RepaintGate();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
    expect(gate.requestPaint()).toBe(true);
    // Nothing was held, so the drag that never happened owes nothing.
    expect(gate.endDrag()).toBe(false);
  });

  test("holds every paint for the length of a drag", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.isDragging).toBe(true);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.requestPaint()).toBe(false);
  });

  test("owes exactly one repaint however many ticks landed mid-drag", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    for (let i = 0; i < 40; i++) gate.requestPaint();
    // One repaint from current state settles all forty of them.
    expect(gate.endDrag()).toBe(true);
    expect(gate.isDragging).toBe(false);
    // And it is not owed twice.
    expect(gate.endDrag()).toBe(false);
  });

  test("owes nothing for a drag no tick interrupted", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });

  test("reopens clean for the next drag", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    expect(gate.endDrag()).toBe(true);

    gate.beginDrag();
    // The previous drag's debt does not carry over.
    expect(gate.endDrag()).toBe(false);

    gate.beginDrag();
    gate.requestPaint();
    expect(gate.endDrag()).toBe(true);
  });

  test("a resize drops the open drag, so paints land again immediately", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("a stray dragend after a resize owes nothing", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.requestPaint();
    gate.resize();
    // The resize repainted from scratch by itself; there is nothing to replay.
    expect(gate.endDrag()).toBe(false);
  });

  test("a resize with no drag open is harmless", () => {
    const gate = new RepaintGate();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
    gate.resize();
    expect(gate.endDrag()).toBe(false);
  });

  test("the scene repaints once for a drag the simulation ticked through", () => {
    const app = scene();
    app.paint(); // first frame
    expect(app.paints).toBe(1);

    app.gate.beginDrag();
    for (let i = 0; i < 12; i++) app.paint(); // sim ticks under the player's finger
    expect(app.paints).toBe(1);

    app.endDrag();
    // Exactly one rebuild, at the end, with the drop already applied.
    expect(app.paints).toBe(2);
  });

  test("the scene keeps painting normally once the drag is over", () => {
    const app = scene();
    app.gate.beginDrag();
    app.paint();
    app.endDrag();
    app.paint();
    app.paint();
    expect(app.paints).toBe(3);
  });
});

